import { defineHandlers } from '@stagecraft/core';
import type { DB } from './seed';

const ONBOARDING_STEPS = 4;

// Keys are "METHOD /path/:param". Mutate ctx.db to persist writes for the session.
export const handlers = defineHandlers<DB>({
  'GET /api/me': ({ db, persona, reply }) => db.users.find((u) => u.id === persona.userId) ?? reply(401, { error: 'Not signed in' }),
  'GET /api/account': ({ db }) => db.account,

  // Newest first, like the real API.
  'GET /api/payments': ({ db }) => [...db.payments].sort((a, b) => b.date.localeCompare(a.date)),
  'POST /api/payments/:id/:verb': ({ db, params, persona, reply }) => {
    const p = db.payments.find((x) => x.id === params.id);
    if (!p) return reply(404, { error: 'Payment not found' });
    if (params.verb !== 'approve' && params.verb !== 'reject') return reply(404, { error: 'Not found' });
    if (persona.role !== 'admin') return reply(403, { error: 'Only admins can approve or reject payments.' });
    if (db.account.status === 'frozen') return reply(409, { error: 'This account is frozen. Payments are paused.' });
    if (p.status !== 'pending_approval') return reply(409, { error: 'This payment is not waiting for approval.' });
    p.status = params.verb === 'approve' ? 'approved' : 'rejected';
    return p;
  },

  'POST /api/onboarding/complete-step': ({ db, persona, reply }) => {
    const u = db.users.find((x) => x.id === persona.userId);
    if (!u) return reply(401, { error: 'Not signed in' });
    u.onboardingStep = Math.min(ONBOARDING_STEPS, u.onboardingStep + 1);
    return u;
  },

  // Served for https://api.ledgerly.example (see apiOrigins).
  'GET /api/agents': ({ db }) => db.agents,
  'PATCH /api/agents/:id': ({ db, params, body, persona, reply }) => {
    const a = db.agents.find((x) => x.id === params.id);
    if (!a) return reply(404, { error: 'Agent not found' });
    if (persona.role !== 'admin') return reply(403, { error: 'Only admins can change agents.' });
    const status = (body as { status?: string } | undefined)?.status;
    if (status !== 'active' && status !== 'paused') return reply(400, { error: 'status must be active or paused' });
    a.status = status;
    return a;
  },
});

