@@ -0,0 +1,25 @@
+import { defineConfig } from '@stagecraft/core';
+import { seed, type DB } from './stagecraft/seed';
+import { handlers } from './stagecraft/mocks';
+import { states } from './stagecraft/states';
+
+export default defineConfig<DB>({
+  devCommand: "npm run dev",
+  devUrl: 'http://localhost:5174',
+  port: 4400,
+  // Requests to these origins never reach a real backend. Add full origins too, e.g. 'https://api.example.com'.
+  apiOrigins: ['/api', 'https://api.ledgerly.example'],
+  handlers,
+  seed,
+  // The assistant chat opens this SSE stream; tapes in stagecraft/tapes play on it.
+  tapes: { endpoint: 'GET /api/assistant/stream', transport: 'sse' },
+  personas: {
+    admin: { label: 'Admin', userId: 'u1', role: 'admin' },
+    member: { label: 'Employee', userId: 'u2', role: 'member' },
+  },
+  defaultPersona: 'admin',
+  states,
+  flags: {
+    // 'new-nav': { default: false, description: 'New navigation' },
+  },
+});

